function getFoodPhoto(category,index,item){
 const name=item?.n||"";
 if(category==="Snacks" && /garlic bread/i.test(name)){
  const photos=FOOD_PHOTOS["Garlic Bread"];
  return photos[index%photos.length];
 }
 if(category==="Desserts & Shakes"){
  if(/lava cake/i.test(name)) return "data:image/webp;base64,";
  if(/tutti frutti/i.test(name)) return "data:image/webp;base64,";
  if(/dip/i.test(name)) return "data:image/webp;base64,";
  if(/butter scotch/i.test(name)) return "data:image/webp;base64,";
  if(/strawberry/i.test(name)) return "data:image/webp;base64,";
  if(/cold coffee/i.test(name)) return "data:image/webp;base64,";
  if(/vanilla/i.test(name)) return "data:image/webp;base64,";
  if(/add ice cream/i.test(name)) return "data:image/webp;base64,";
  if(/chocolate shake/i.test(name)) return "data:image/webp;base64,";
  if(/oreo/i.test(name)) return "data:image/webp;base64,";
  if(/brownie/i.test(name)) return "data:image/webp;base64,";
  if(/ice cream/i.test(name)) return "data:image/webp;base64,";
 }

 const photos=FOOD_PHOTOS[category];
 return photos[index%photos.length];
}
function getPizzaPhoto(item,index){
 const n=item.n.toLowerCase();
 const named=[
  [/margherita|single cheese/,0],[/tomato/,1],[/onion/,2],[/corn/,3],[/capsicum|pepper/,4],[/paneer/,5]
 ];
 for(const [re,photoIndex] of named){if(re.test(n))return PIZZA_PHOTOS[photoIndex]}
 return PIZZA_PHOTOS[index%PIZZA_PHOTOS.length];
}
const L=["Regular","Medium","Large"],S=["Serves 1","Serves 2","Serves 4"];
const tabs=document.getElementById("tabs"),grid=document.getElementById("grid"),size=document.getElementById("size");
const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target)}}),{threshold:.1});
function show1(k){
 [...tabs.children].forEach(b=>b.classList.toggle("on",b.dataset.k===k));
 const d=D[k];
 size.innerHTML=d.s?L.map((l,i)=>`<span>${l} · ${S[i]}</span>`).join(""):"";
 grid.innerHTML=d.i.map((x,i)=>`<div class="card" style="transition-delay:${(i%8)*60}ms">${(PIZZA_CATEGORIES.has(k)||FOOD_PHOTOS[k])?`<img class="food-img" src="${PIZZA_CATEGORIES.has(k)?getPizzaPhoto(x,i):getFoodPhoto(k,i,x)}" alt="${x.n}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.outerHTML='<div class=\'food-fallback\' aria-label=\'Food photo unavailable\'>${x.e}</div>'">`:`<span class="e">${x.e}</span>`}${i<2&&d.s?'<span class="tag">HOT</span>':""}<h3>${x.n}</h3><div class="pr">${x.p.map((v,j)=>`<b data-j="${j}" class="${x.p.length>1&&j==0?'sel':''}">${x.p.length>1?L[j][0]+' ':''}₹${v}</b>`).join("")}</div><button class="add" data-k="${k}" data-i="${i}">+ Add</button></div>`).join("");
 grid.querySelectorAll(".card").forEach(c=>io.observe(c));
}
Object.keys(D).forEach((k,i)=>{const b=document.createElement("button");b.textContent=k;b.dataset.k=k;b.onclick=()=>show(k);tabs.append(b)});
function show(k){
 if(k!=="All"){show1(k);return}
 let h="";Object.keys(D).forEach(c=>{show1(c);h+=`<h3 class="ch" style="grid-column:1/-1;font-size:1.5rem;margin-top:18px;border-left:6px solid var(--red);padding-left:12px">${c}</h3>`+grid.innerHTML});
 grid.innerHTML=h;size.innerHTML=L.map((l,i)=>`<span>${l} · ${S[i]}</span>`).join("");
 [...tabs.children].forEach(b=>b.classList.toggle("on",b.dataset.k==="All"));
 grid.querySelectorAll(".card").forEach(c=>io.observe(c));
}
