const NO="919911273199",C={},$=id=>document.getElementById(id);
function getCartTotals(){
 const entries=Object.entries(C);let total=0,count=0;
 for(const [,item] of entries){total+=item.p*item.q;count+=item.q;}
 return {entries,total,count};
}
function draw(){
 const {entries,total,count}=getCartTotals();
 $("items").innerHTML=entries.length?entries.map(([key,item])=>`
  <div class="it">
   <div class="it-info"><div class="it-name">${escapeHtml(item.n)}${item.z?` (${escapeHtml(item.z)})`:""}</div><small>₹${item.p} × ${item.q} = ₹${item.p*item.q}</small></div>
   <div class="it-actions"><div class="q"><button type="button" data-k="${encodeURIComponent(key)}" data-d="-1" aria-label="Decrease ${escapeHtml(item.n)} quantity">−</button><b>${item.q}</b><button type="button" data-k="${encodeURIComponent(key)}" data-d="1" aria-label="Increase ${escapeHtml(item.n)} quantity">+</button></div><button type="button" class="remove-item" data-remove="${encodeURIComponent(key)}">Remove</button></div>
  </div>`).join("") : "<p class='em'>Your bag is empty 🍕</p>";
 $("tt").textContent="₹"+total;$("cnt").textContent=count;
 const navCount=$("navCnt");if(navCount)navCount.textContent=count;
 const send=$("send");send.disabled=!count;
 updateCartRules();
}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));}
function updateCartRules(){
 const type=$("orderType").value, isDelivery=type==="Delivery";
 $("addressLabel").textContent=isDelivery?"Delivery address":"Pickup note (optional)";
 $("ad").placeholder=isDelivery?"House / street / area":"Optional note";
 $("ad").required=isDelivery;
 const {count,total}=getCartTotals();
 const enough=!isDelivery||total>=250;
 $("send").disabled=!count||!enough;
 $("cartNote").textContent=isDelivery?"Minimum order ₹250 for delivery.":"Self pickup selected — no minimum order.";
 $("cartStatus").textContent=count&&!enough?`Add ₹${250-total} more for delivery, or choose self pickup.`:"";
}
function buildWhatsAppMessage(){
 const {entries,total}=getCartTotals(),type=$("orderType").value;
 const lines=entries.map(([key,item],i)=>`${i+1}. ${item.n}${item.z?` (${item.z})`:""} × ${item.q} = ₹${item.p*item.q}`);
 return ["Hello Da Pizza Hub Hansi! 🍕","I would like to place an order:","",...lines,"",`Order type: ${type}`,`Total: ₹${total}`,`Name: ${$("nm").value.trim()}`,type==="Delivery"?`Delivery address: ${$("ad").value.trim()}`:($("ad").value.trim()?`Pickup note: ${$("ad").value.trim()}`:""),"","Please confirm my order. Thank you!"].filter(Boolean).join("\n");
}
function sendWhatsAppOrder(){
 const {count,total}=getCartTotals(),name=$("nm").value.trim(),address=$("ad").value.trim(),type=$("orderType").value;
 if(!count){$("cartStatus").textContent="Your bag is empty. Add an item first.";return;}
 if(!name){$("nm").focus();$("cartStatus").textContent="Please enter your name.";return;}
 if(type==="Delivery"&&!address){$("ad").focus();$("cartStatus").textContent="Please enter your delivery address.";return;}
 if(type==="Delivery"&&total<250){$("cartStatus").textContent=`Delivery minimum is ₹250. Add ₹${250-total} more or choose self pickup.`;return;}
 const message=buildWhatsAppMessage();
 const confirmed=window.confirm(`Please confirm your ${type.toLowerCase()} order.\n\nItems: ${count}\nTotal: ₹${total}\n\nContinue to WhatsApp?`);
 if(!confirmed)return;
 const url="https://wa.me/"+NO+"?text="+encodeURIComponent(message);
 window.open(url,"_blank","noopener,noreferrer");
 $("cartStatus").textContent="WhatsApp opened with your order. Please press Send in WhatsApp to place it.";
}
$("grid").addEventListener("click",e=>{
 const choice=e.target.closest(".pr b");
 if(choice&&choice.parentNode.children.length>1){[...choice.parentNode.children].forEach(c=>c.classList.remove("sel"));choice.classList.add("sel");}
 const button=e.target.closest(".add");
 if(!button)return;
 const card=button.closest(".card");if(!card)return;
 const item=D[button.dataset.k]?.i?.[Number(button.dataset.i)];if(!item)return;
 const selected=card.querySelector(".pr b.sel")||card.querySelector(".pr b");
 const priceIndex=item.p.length>1&&selected?Number(selected.dataset.j||0):0;
 const price=item.p[priceIndex];if(!Number.isFinite(price))return;
 const key=item.n+(item.p.length>1?`-${priceIndex}`:"-single");
 if(!C[key])C[key]={n:item.n,z:item.p.length>1?L[priceIndex]:"",p:price,q:0};
 C[key].q++;draw();button.textContent="✓ Added";setTimeout(()=>button.textContent="+ Add",900);
 $("bag").animate([{transform:"scale(1.08)"},{transform:"scale(1)"}],{duration:220});
});
$("items").addEventListener("click",e=>{
 const remove=e.target.closest("button[data-remove]");
 if(remove){const key=decodeURIComponent(remove.dataset.remove);delete C[key];draw();return;}
 const button=e.target.closest("button[data-k][data-d]");
 if(button){const key=decodeURIComponent(button.dataset.k),item=C[key];if(!item)return;item.q+=Number(button.dataset.d);if(item.q<=0)delete C[key];draw();}
});
$("bag").onclick=()=>$("dr").classList.add("open");
$("x").onclick=()=>$("dr").classList.remove("open");
$("nm").addEventListener("input",()=>$("cartStatus").textContent="");
$("ad").addEventListener("input",()=>$("cartStatus").textContent="");
$("orderType").addEventListener("change",updateCartRules);
$("send").addEventListener("click",sendWhatsAppOrder);
document.querySelector(".combo").addEventListener("click",e=>{const b=e.target.closest(".cadd");if(!b)return;const key="c"+b.dataset.n;C[key]=C[key]||{n:b.dataset.n,z:"Combo",p:+b.dataset.p,q:0};C[key].q++;draw();b.textContent="✓ Added";setTimeout(()=>b.textContent="+ Add",900);$("bag").animate([{transform:"scale(1.25)"},{transform:"scale(1)"}],{duration:300})});
draw();
