const navToggle=document.getElementById("navToggle"),navLinks=document.getElementById("navLinks");
if(navToggle&&navLinks){navToggle.addEventListener("click",()=>{const open=navLinks.classList.toggle("open");navToggle.setAttribute("aria-expanded",String(open));navToggle.textContent=open?"✕":"☰"});navLinks.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{navLinks.classList.remove("open");navToggle.setAttribute("aria-expanded","false");navToggle.textContent="☰"}))}
const navCart=document.getElementById("navCart");if(navCart)navCart.addEventListener("click",()=>document.getElementById("bag").click());
const oldDraw=draw;draw=function(){oldDraw();const n=document.getElementById("navCnt");if(n)n.textContent=document.getElementById("cnt").textContent};
const navAnchors=[...document.querySelectorAll(".nav-links a")];const navSections=[...document.querySelectorAll("#home,#menu,#combos,#offers,#about,#contact")];if("IntersectionObserver" in window){const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navAnchors.forEach(a=>a.classList.toggle("active",a.getAttribute("href")==="#"+entry.target.id))}}),{rootMargin:"-35% 0px -55% 0px"});navSections.forEach(s=>navObserver.observe(s))}
